/**
 * BI-20.2 —— 全局参数矩阵定义与解析器（只做定义与解析，不做消费接线）。
 *
 * kimi 对应物: apps/kimi-code/src/cli/sub/args.ts（全局旗标面）
 * 差异边界:
 *   - 本卡仅提供 GLOBAL_ARGS 矩阵 + parseGlobalArgs 纯解析器；解析结果的
 *     消费（--agent-file 加载 agent 定义、--add-dir 注入可访问目录、
 *     --prompt 无头启动、--output-format 流式输出）归属 BI-20.1 / 后续装配方；
 *   - 仅支持长参：`--flag value` 与 `--flag=value` 两种传值形式；不支持
 *     短参捆绑；单值 flag 重复出现 → duplicate-flag；可重复 flag（--add-dir）
 *     聚合为数组；
 *   - 结构化错误：unknown-flag / missing-value / invalid-value / duplicate-flag；
 *   - 空格传值时，后随以 `-` 开头的 token 视为缺值（需要 `-` 开头的字面值
 *     请用等号形式，如 `--prompt=--continue`）；单独 `-` 同理视为缺值；
 *   - `--` 之后一律视为位置参数；裸位置参数（如子命令名）收进 positionals，
 *     子命令派发归属装配方，不在本解析器报错。
 */

export interface GlobalArgSpec {
  /** 长参名（含前导 --）。 */
  flag: string;
  /** 值占位说明（如 "<path.md>"）。 */
  valueName: string;
  /** 一句话说明（帮助渲染用）。 */
  description: string;
  /** 是否可重复出现（重复时聚合为数组）。 */
  repeatable: boolean;
  /** 合法值白名单；缺省不校验值域。 */
  allowedValues?: readonly string[];
}

/** 全局参数矩阵（合约定义；消费接线归属 BI-20.1 / 后续装配方）。 */
export const GLOBAL_ARGS: readonly GlobalArgSpec[] = [
  {
    flag: "--agent-file",
    valueName: "<path.md>",
    description: "agent 定义文件（markdown）路径",
    repeatable: false,
  },
  {
    flag: "--add-dir",
    valueName: "<dir>",
    description: "附加可访问工作目录（可多次出现）",
    repeatable: true,
  },
  {
    flag: "--prompt",
    valueName: "<text>",
    description: "无头模式提示词",
    repeatable: false,
  },
  {
    flag: "--output-format",
    valueName: "<format>",
    description: "输出格式",
    repeatable: false,
    allowedValues: ["stream-json"],
  },
  {
    flag: "--max-rounds",
    valueName: "<n>",
    description: "无头会话模型回合上限（正整数，缺省 8）",
    repeatable: false,
  },
];

export type OutputFormat = "stream-json";

export interface ParsedArgs {
  /** --agent-file 的值。 */
  agentFile?: string;
  /** --add-dir 聚合值（保持出现顺序）。 */
  addDirs: string[];
  /** --prompt 的值。 */
  prompt?: string;
  /** --output-format 的值（已过白名单校验）。 */
  outputFormat?: OutputFormat;
  /** --max-rounds 的值（已过正整数校验；缺省回合上限由 headless 决定）。 */
  maxRounds?: number;
  /** 位置参数（`--` 后或裸词；子命令派发归属装配方）。 */
  positionals: string[];
}

export type ArgErrorCode = "unknown-flag" | "missing-value" | "invalid-value" | "duplicate-flag";

export class ArgParseError extends Error {
  constructor(
    readonly code: ArgErrorCode,
    message: string,
    readonly flag?: string,
  ) {
    super(message);
    this.name = "ArgParseError";
  }
}

/** 解析全局参数矩阵；未知/缺值/非法值/重复单值均抛结构化 ArgParseError。 */
export function parseGlobalArgs(argv: readonly string[]): ParsedArgs {
  const specs = new Map(GLOBAL_ARGS.map((spec) => [spec.flag, spec]));
  const result: ParsedArgs = { addDirs: [], positionals: [] };
  const seen = new Set<string>();
  let afterDoubleDash = false;

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];
    i += 1;
    if (token === undefined) break; // noUncheckedIndexedAccess 防御

    if (afterDoubleDash) {
      result.positionals.push(token);
      continue;
    }
    if (token === "--") {
      afterDoubleDash = true;
      continue;
    }
    if (!token.startsWith("--")) {
      result.positionals.push(token); // 裸词（子命令名等），派发归属装配方
      continue;
    }

    let flag = token;
    let inlineValue: string | undefined;
    const eq = token.indexOf("=");
    if (eq !== -1) {
      flag = token.slice(0, eq);
      inlineValue = token.slice(eq + 1);
    }

    const spec = specs.get(flag);
    if (spec === undefined) {
      throw new ArgParseError(
        "unknown-flag",
        `未知参数: ${flag}（支持: ${GLOBAL_ARGS.map((s) => s.flag).join(" ")}）`,
        flag,
      );
    }
    if (!spec.repeatable && seen.has(flag)) {
      throw new ArgParseError("duplicate-flag", `参数重复: ${flag}（该参数只允许出现一次）`, flag);
    }
    seen.add(flag);

    let value = inlineValue;
    if (value === undefined) {
      const next = argv[i];
      if (next === undefined || next.startsWith("-")) {
        throw new ArgParseError(
          "missing-value",
          `参数 ${flag} 缺少值（需要 ${spec.valueName}）`,
          flag,
        );
      }
      value = next;
      i += 1;
    }

    if (spec.allowedValues !== undefined && !spec.allowedValues.includes(value)) {
      throw new ArgParseError(
        "invalid-value",
        `参数 ${flag} 的值非法: ${value}（允许: ${spec.allowedValues.join(" | ")}）`,
        flag,
      );
    }

    if (spec.flag === "--agent-file") result.agentFile = value;
    else if (spec.flag === "--add-dir") result.addDirs.push(value);
    else if (spec.flag === "--prompt") result.prompt = value;
    else if (spec.flag === "--output-format") result.outputFormat = value as OutputFormat;
    else if (spec.flag === "--max-rounds") {
      if (!/^[1-9]\d*$/.test(value)) {
        throw new ArgParseError("invalid-value", `参数 --max-rounds 的值非法: ${value}（需要正整数）`, "--max-rounds");
      }
      result.maxRounds = Number(value);
    }
  }

  return result;
}

/**
 * BI-23.1 —— 无头走骨架：把 117 卡器官缝成一条可运行的端到端链路。
 *
 * 装配序遵循 RULE-BI-07 定版的 kimi 装配参考（devlog #150）：
 * main 分发 → 会话/配置 → agent 循环 → 工具/权限/钩子。本模块是"缺的那根线"：
 * 模型对话驱动器（问模型 → 收流事件 → 拼工具调用 → 回填结果 → 直到最终文本），
 * 上承 adapters 的 StreamEvent/AgentMessage 线合约（BI-23.3 换真实 SSE 驱动零返工），
 * 下接 BI-07 AgentLoop 工具流水线、BI-06.5 权限门、BI-06.4 钩子、BI-03 JSONL 会话。
 *
 * 骨架期显式降级（不伪造能力）：
 * - 权限 ask 决策：无头无 TTY 无审批 UI → 结构化拒绝回喂模型（BI-23.2 提供 ask 回路）；
 * - 信任门：缺省恒 'trusted'（骨架策略；真实信任门接线归后续装配卡）；
 * - 子命令生态：main 分发只挂真实无头路径，其余子命令结构化"未接线"（不假冒）。
 *
 * stream-json 输出合约：逐行透传 StreamEvent（BI-04.2 七类事件原样 JSON），
 * 末行追加会话级 { type:"session_done", ... } 汇总。
 */
import {
	AgentLoop,
	type ToolCall,
	type ToolExecutor,
	type ToolResult,
} from "../agent";
import {
	type AgentMessage,
	type ContentBlock,
	type StopReason,
	type StreamEvent,
	type ToolDefinition,
	type ToolResultBlock,
	type TextBlock,
	type ToolUseBlock,
} from "../adapters/deepseek-adapter";
import { PermissionGate } from "../guard/permission-gate";
import type { PermissionRequest } from "../guard/types";
import type { WorkspaceTrustState } from "../guard/workspace-trust";
import { HookRunner, type HookSpawnImpl } from "../hooks/hook-runner";
import type { HookRunRecord } from "../hooks/types";
import { loadHooksConfig } from "../config/hooks-adapter";
import type { HooksSection } from "../config/schema";
import { scanShell } from "../sandbox/shell-scan";
import { SessionManager } from "../session/manager";
import type { AppendEntryInput, JsonValue, SessionEntry } from "../session/types";

/** 模型端口：与 adapters 线合约对齐的最小驱动面（真实 SSE 驱动 BI-23.3 接入）。 */
export interface ModelPort {
	stream(input: {
		messages: readonly AgentMessage[];
		tools: readonly ToolDefinition[];
		signal?: AbortSignal;
	}): AsyncIterable<StreamEvent>;
}

/** 工具绑定：定义（喂模型）+ 执行体（真实器官）+ 权限面（argSummary）。 */
export interface ToolBinding {
	readonly definition: ToolDefinition;
	/** 只读工具（RWLock 读锁语义 + 只读排重资格）。 */
	readonly readOnly: boolean;
	/** 权限门 argSummary（缺省取 JSON 序列化截断）。 */
	readonly argSummary?: (args: unknown) => string;
	execute(args: unknown, signal: AbortSignal): Promise<unknown> | unknown;
}

export interface HeadlessOptions {
	readonly prompt: string;
	readonly cwd: string;
	readonly model: ModelPort;
	readonly tools: readonly ToolBinding[];
	/** config.toml [[hooks]] 分区（经 BI-01.1 装载适配器映射到 runner 契约）。 */
	readonly hooks?: HooksSection;
	/** 权限门初始模式（缺省 "auto"：全自动放行 + 审计标记；manual 下 ask 走降级拒绝）。 */
	readonly permissionMode?: "manual" | "auto" | "yolo";
	/**
	 * 注入门禁（BI-28.3 接线）：装配层已按 config [permission] mode/rules 建好
	 * 门禁时注入（与 /permissions 命令面共享实例）；缺省按 permissionMode 自建
	 * （缺省 auto：无头路径 ask 不可达，走结构化降级拒绝）。
	 */
	readonly gate?: PermissionGate;
	/** 会话存储根（缺省 SessionManager 默认根）。 */
	readonly sessionsRoot?: string;
	readonly sessionId?: string;
	/** 信任门（骨架缺省恒 trusted）。 */
	readonly trust?: (root: string) => WorkspaceTrustState;
	/** spawn 替身（钩子测试注入；缺省真实子进程）。 */
	readonly hookSpawn?: HookSpawnImpl;
	/** 输出汇（缺省 process.stdout 逐行；测试注入收集）。 */
	readonly out?: (line: string) => void;
	/** 模型回合上限（防失控，缺省 8）。 */
	readonly maxRounds?: number;
}

export interface HeadlessResult {
	readonly exitCode: number;
	readonly sessionId: string;
	readonly finalText: string;
	readonly rounds: number;
	readonly toolResults: readonly ToolResult[];
	readonly hookRecords: readonly HookRunRecord[];
	/** 权限审计轨迹（工具序）。 */
	readonly permissionDecisions: ReadonlyArray<{ tool: string; decision: string }>;
}

/** 工具调用增量按 index 拼装缓冲（BI-23.2 TUI 挂载复用）。 */
export class ToolCallAssembler {
	#calls = new Map<number, { id?: string; name?: string; args: string }>();

	push(event: Extract<StreamEvent, { type: "tool_call_delta" }>): void {
		const current = this.#calls.get(event.index) ?? { args: "" };
		if (event.id !== undefined) current.id = event.id;
		if (event.name !== undefined) current.name = event.name;
		current.args += event.argumentsDelta;
		this.#calls.set(event.index, current);
	}

	/** 按 index 升序产出拼装完成的调用；清空缓冲。 */
	drain(): ToolCall[] {
		const calls: ToolCall[] = [];
		for (const index of [...this.#calls.keys()].sort((a, b) => a - b)) {
			const partial = this.#calls.get(index)!;
			let parsed: unknown;
			try {
				parsed = JSON.parse(partial.args === "" ? "{}" : partial.args);
			} catch {
				parsed = { __raw: partial.args };
			}
			calls.push({ id: partial.id ?? `call_${index}`, name: partial.name ?? "unknown", args: parsed });
		}
		this.#calls = new Map();
		return calls;
	}
}

/** 会话级装配错误（main 捕获转退出码）。 */
export class HeadlessError extends Error {
	readonly code: "hook-blocked" | "adapter-error" | "rounds-exceeded";
	constructor(code: "hook-blocked" | "adapter-error" | "rounds-exceeded", message: string) {
		super(message);
		this.name = "HeadlessError";
		this.code = code;
	}
}

/**
 * 无头走骨架主流程：一条带真实工具调用、权限门、钩子触发与 JSONL 落盘的会话。
 */
export async function runHeadless(options: HeadlessOptions): Promise<HeadlessResult> {
	const out = options.out ?? ((line: string) => process.stdout.write(`${line}\n`));
	const emit = (event: unknown): void => out(JSON.stringify(event));
	const toolResults: ToolResult[] = [];
	const hookRecords: HookRunRecord[] = [];
	const permissionDecisions: Array<{ tool: string; decision: string }> = [];

	// ---- 装配序 ①：钩子（config [[hooks]] → BI-01.1 适配器 → BI-06.4 runner）----
	const loadedHooks = loadHooksConfig(options.hooks ?? { enabled: true, entries: [] });
	hookRecords.push(...loadedHooks.dropped.map((drop) => ({
		hookId: `hooks[${drop.index}]`,
		event: "SessionStart" as const,
		command: "",
		status: "bad-output" as const,
		durationMs: 0,
		warning: `hook-load-dropped: ${drop.reason}`,
	})));
	const hookRunner = new HookRunner({
		config: loadedHooks.config,
		trust: options.trust ?? (() => "trusted"),
		scanShell,
		...(options.hookSpawn !== undefined ? { spawnImpl: options.hookSpawn } : {}),
	});
	const hookInput = (event: Parameters<HookRunner["run"]>[0], tool?: string, args?: unknown) => ({
		event,
		...(tool !== undefined ? { tool } : {}),
		...(args !== undefined ? { args } : {}),
		timestamp: new Date().toISOString(),
	});

	// ---- 装配序 ②：会话（BI-03 JSONL）----
	const manager = new SessionManager(options.sessionsRoot !== undefined ? { rootDir: options.sessionsRoot } : {});
	const session = await manager.createSession({
		...(options.sessionId !== undefined ? { sessionId: options.sessionId } : {}),
		title: options.prompt.slice(0, 80),
		cwd: options.cwd,
	});
	const sessionId = session.sessionId;

	// SessionStart 钩子：block 即拒开会话（fail-closed，结构化退出）。
	const startOutcome = await hookRunner.run("SessionStart", { ...hookInput("SessionStart"), sessionId, cwd: options.cwd });
	hookRecords.push(...startOutcome.records);
	if (startOutcome.action === "block") {
		emit({ type: "session_done", sessionId, exit: "hook-blocked", reason: startOutcome.reason });
		throw new HeadlessError("hook-blocked", `SessionStart 钩子阻断会话: ${startOutcome.reason ?? "no reason"}`);
	}

	// ---- 装配序 ③：权限门（BI-06.5）与工具注册表 ----
	const gate = options.gate ?? new PermissionGate({ mode: options.permissionMode ?? "auto" });
	const registry = new Map<string, ToolBinding>();
	for (const binding of options.tools) registry.set(binding.definition.name, binding);
	const readOnlyTools = new Set(options.tools.filter((t) => t.readOnly).map((t) => t.definition.name));

	/** 装配执行体：权限门 → PreToolUse 钩子 → 真实工具 → PostToolUse 钩子（AgentLoop 钩子固定序之外的装配层环节）。 */
	const assembledExecutor: ToolExecutor = async (call: ToolCall, signal: AbortSignal): Promise<unknown> => {
		const binding = registry.get(call.name);
		if (binding === undefined) throw new Error(`unknown-tool: ${call.name}`);
		const argSummary = binding.argSummary?.(call.args) ?? String(JSON.stringify(call.args) ?? "undefined").slice(0, 200);

		const decision = gate.check({ tool: call.name, argSummary, mode: gate.mode } satisfies PermissionRequest);
		permissionDecisions.push({ tool: call.name, decision: decision.decision });
		if (decision.decision === "deny") throw new Error(`permission-denied${decision.feedback !== undefined ? `: ${decision.feedback}` : ""}`);
		if (decision.decision === "ask") {
			// 骨架期降级：无头无审批 UI，结构化拒绝回喂模型（BI-23.2 提供 ask 回路）。
			throw new Error("permission-ask-unavailable-in-headless");
		}

		const pre = await hookRunner.run("PreToolUse", { ...hookInput("PreToolUse", call.name, call.args), sessionId, cwd: options.cwd });
		hookRecords.push(...pre.records);
		if (pre.action === "block") throw new Error(`hook-blocked: ${pre.reason ?? "no reason"}`);

		const value = await binding.execute(call.args, signal);

		const post = await hookRunner.run("PostToolUse", { ...hookInput("PostToolUse", call.name, call.args), sessionId, cwd: options.cwd });
		hookRecords.push(...post.records); // PostToolUse block 仅记录（执行已完成），不阻断
		return value;
	};

	const agentLoop = new AgentLoop({
		execute: assembledExecutor,
		readOnlyTools,
	});

	// ---- 装配序 ④：模型对话驱动器 ----
	const messages: AgentMessage[] = [{ role: "user", content: options.prompt }];
	const maxRounds = options.maxRounds ?? 8;
	let finalText = "";
	let rounds = 0;

	let parentId: string | undefined;
	const rootEntry = await manager.append(sessionId, null, { type: "user", payload: { text: options.prompt } as unknown as JsonValue });
	parentId = rootEntry.id;

	const appendChained = async (input: AppendEntryInput): Promise<SessionEntry> => {
		const entry = await manager.append(sessionId, parentId ?? null, input);
		parentId = entry.id;
		return entry;
	};

	while (rounds < maxRounds) {
		rounds += 1;
		// 状态机契约：beginTurn 只走 idle→thinking；工具回合落定后已在 thinking，
		// 直接进入下一轮 executeTools（thinking→tool-executing）。
		if (agentLoop.state === "idle") agentLoop.beginTurn();
		let text = "";
		const blocks: ContentBlock[] = [];
		const assembler = new ToolCallAssembler();
		let stop: StopReason = null;

		for await (const event of options.model.stream({ messages, tools: options.tools.map((t) => t.definition) })) {
			if (event.type === "content_delta") {
				text += event.delta;
			} else if (event.type === "tool_call_delta") {
				assembler.push(event);
			} else if (event.type === "done") {
				stop = event.stopReason;
			} else if (event.type === "error") {
				throw new HeadlessError("adapter-error", `${event.error.code}: ${event.error.message}`);
			}
			emit(event);
		}

		if (stop === "stop" || stop === null) {
			if (text !== "") {
				const textBlock: TextBlock = { type: "text", text };
				blocks.push(textBlock);
			}
			finalText = text;
			messages.push({ role: "assistant", content: blocks });
			await appendChained({ type: "assistant", payload: { content: blocks } as unknown as JsonValue });
			agentLoop.finishTurn();
			emit({ type: "session_done", sessionId, exit: "ok", rounds, finalText });
			return {
				exitCode: 0,
				sessionId,
				finalText,
				rounds,
				toolResults,
				hookRecords,
				permissionDecisions,
			};
		}

		if (stop !== "tool_use") {
			agentLoop.finishTurn();
			throw new HeadlessError("adapter-error", `不可继续的停止原因: ${String(stop)}`);
		}

		// tool_use 回合：assistant(含 tool_use 块) → 逐调用流水线 → tool_result 回填
		const calls = assembler.drain();
		const useBlocks: ToolUseBlock[] = calls.map((call) => ({ type: "tool_use", id: call.id, name: call.name, input: call.args }));
		messages.push({ role: "assistant", content: [...blocks, ...useBlocks] });
		await appendChained({ type: "assistant", payload: { content: [...blocks, ...useBlocks] } as unknown as JsonValue });

		const results = await agentLoop.executeTools(calls);
		toolResults.push(...results);

		const resultBlocks: ToolResultBlock[] = [];
		for (const call of calls) {
			const result = results.find((r) => r.id === call.id);
			const block: ToolResultBlock = {
				type: "tool_result",
				toolUseId: call.id,
				content: result === undefined ? "lost-result" : result.ok ? safeStringify(result.value) : `error: ${result.error ?? "unknown"}`,
				isError: result === undefined || !result.ok,
			};
			resultBlocks.push(block);
			await appendChained(
				{ type: "tool_call", payload: { name: call.name, args: call.args } as unknown as JsonValue, toolCallId: call.id, toolName: call.name },
			);
			await appendChained(
				{
					type: "tool_result",
					payload: (result === undefined ? { ok: false } : { ok: result.ok, ...(result.ok ? { value: result.value } : { error: result.error }) }) as unknown as JsonValue,
					toolCallId: call.id,
					toolName: call.name,
				},
			);
		}
		messages.push({ role: "user", content: resultBlocks });
	}

	throw new HeadlessError("rounds-exceeded", `模型回合超过上限 ${maxRounds}`);
}

function safeStringify(value: unknown): string {
	if (typeof value === "string") return value;
	try {
		return JSON.stringify(value) ?? String(value);
	} catch {
		return String(value);
	}
}

/**
 * BI-23.1 —— bi 主分发（kimi 装配参考形状：main → handleMainCommand → TUI/无头）。
 *
 * 接线现状（BI-24.1 起八子命令查表派发）：
 * - 真实路径：无头会话（--prompt）——ModelPort 未注入时从配置装配（BI-02 凭据门 +
 *   BI-04.2 双模态 SSE 驱动），装配失败结构化退出码 3；
 * - 子命令：init/session/fork/export/transfer/acp/upgrade/doctor 全部经
 *   cli/commands/dispatch.ts handleSubcommand 派发到真实处理器（器官在库即用，
 *   缺器官结构化上报，不假冒成功）；未知子命令仍 exit 2；
 * - --version 直读 @bi/core VERSION。
 */
import { ConfigService } from "../config/config-service";
import { ConfigError } from "../config/schema";
import { parseGlobalArgs, ArgParseError } from "./commands/args";
import {
	findSubcommandIndex,
	handleSubcommand,
	SUBCOMMANDS,
	type SubcommandDeps,
} from "./commands/dispatch";
import { ModelPortConfigError, resolveModelPort } from "./model-port";
import { runHeadless, type HeadlessOptions, type ModelPort } from "./headless";
import { PermissionGate } from "../guard/permission-gate";
import type { PermissionRule } from "../guard/types";
import { permissionModeFromConfig } from "./permission-mode";

export interface RunBiOptions {
	/** 无头模型端口（缺省 = 从配置文件装配真实 BI-04.2 驱动；测试注入替身）。 */
	model?: ModelPort;
	/** 透传 runHeadless 其余选项（测试注入 sessionsRoot/cwd/tools/hooks 等；homeDir 供 ConfigService 注入）。 */
	headless?: Partial<
		Pick<HeadlessOptions, "cwd" | "sessionsRoot" | "tools" | "hooks" | "permissionMode" | "trust" | "hookSpawn" | "maxRounds" | "gate"> & { homeDir: string }
	>;
	/** 输出汇（缺省 stdout）。 */
	out?: (line: string) => void;
	/** 诊断输出汇（缺省 stderr）。 */
	err?: (line: string) => void;
	/** BI-24.1 子命令注入面（临时根目录/IO/upgrade 检查替身等，详见 dispatch.ts）。 */
	deps?: SubcommandDeps;
}

const USAGE = `bi — CLI Agent（行走骨架）

用法:
  bi --prompt "<text>" [--output-format stream-json]   无头会话（骨架真实路径）
  bi <subcommand> [args]                               子命令（见下）
  bi --version                                         版本

子命令: ${SUBCOMMANDS.join(" / ")}
`;

/** bi 主入口：argv 分发，返回进程退出码。 */
export async function runBi(argv: readonly string[], options: RunBiOptions = {}): Promise<number> {
	const out = options.out ?? ((line: string) => process.stdout.write(`${line}\n`));
	const err = options.err ?? ((line: string) => process.stderr.write(`${line}\n`));

	if (argv.includes("--version")) {
		const { VERSION } = await import("../index");
		out(`bi ${VERSION}`);
		return 0;
	}
	if (argv.length === 0 || argv.includes("--help") || argv.includes("-h")) {
		err(USAGE);
		return argv.length === 0 ? 2 : 0;
	}

	// BI-24.1：子命令 argv 切分——首个子命令裸词之后的 token 不进全局参数矩阵，
	// 原样交给子命令自持旗标面（--limit / --format / --no-net 等不由全局解析报错）。
	const subIndex = findSubcommandIndex(argv);

	let parsed;
	try {
		parsed = parseGlobalArgs(subIndex === -1 ? argv : argv.slice(0, subIndex));
	} catch (cause) {
		if (cause instanceof ArgParseError) {
			err(`bi: 参数错误 [${cause.code}]: ${cause.message}`);
			return 2;
		}
		throw cause;
	}

	const subcommand = subIndex === -1 ? parsed.positionals[0] : argv[subIndex];
	if (subcommand !== undefined) {
		if (!SUBCOMMANDS.includes(subcommand)) {
			err(`bi: 未知子命令 "${subcommand}"`);
			err(USAGE);
			return 2;
		}
		// 查表派发：headless 注入面（cwd/homeDir/sessionsRoot）同时作为子命令缺省
		// 注入（deps 显式值优先），两条路径共享同一注入语义。
		const h = options.headless ?? {};
		const deps: SubcommandDeps = {
			...(h.cwd !== undefined ? { cwd: h.cwd } : {}),
			...(h.homeDir !== undefined ? { homeDir: h.homeDir } : {}),
			...(h.sessionsRoot !== undefined ? { sessionsRoot: h.sessionsRoot } : {}),
			...options.deps,
		};
		if (deps.buildModelPort === undefined) {
			// BI-25.2：acp session/prompt 生产面——配置装配惰性 memo 化（每进程装配一次）。
			// homeDir 取 deps.homeDir ?? h.homeDir：测试可注入空目录实现零外呼确定性。
			const factoryHomeDir = deps.homeDir ?? h.homeDir;
			let memoPort: Promise<ModelPort> | undefined;
			deps.buildModelPort = () => {
				memoPort ??= (async () => {
					const service = new ConfigService({
						...(factoryHomeDir !== undefined ? { homeDir: factoryHomeDir } : {}),
					});
					const config = await service.load();
					const selection = resolveModelPort(config, {
						resolveApiKey: (name) => service.resolveProviderApiKey(name),
					});
					err(`bi: 模型已装配 provider=${selection.providerName} mode=${selection.mode} model=${selection.wireModel}`);
					return selection.port;
				})();
				return memoPort;
			};
		}
		const restArgs = subIndex === -1 ? parsed.positionals.slice(1) : argv.slice(subIndex + 1);
		return handleSubcommand(subcommand, restArgs, { out, err }, deps);
	}

	if (parsed.prompt === undefined || parsed.prompt === "") {
		err('bi: 无头会话需要 --prompt "<text>"');
		return 2;
	}

	const h = options.headless ?? {};
	let model = options.model;
	let configGate: PermissionGate | undefined;
	if (model === undefined) {
		// BI-23.3：真实驱动装配 = 配置装载（三级 TOML+env）→ BI-02 凭据门 → BI-04.2 双模态适配器。
		try {
			const service = new ConfigService({
				...(h.homeDir !== undefined ? { homeDir: h.homeDir } : {}),
				...(h.cwd !== undefined ? { workDir: h.cwd } : {}),
			});
			const config = await service.load();
			const selection = resolveModelPort(config, {
				resolveApiKey: (name) => service.resolveProviderApiKey(name),
			});
			err(`bi: 模型已装配 provider=${selection.providerName} mode=${selection.mode} model=${selection.wireModel}`);
			model = selection.port;
			// BI-28.3 接线:config [permission] mode → 门禁三态;规则表灌入(config 规则
			// 无 scope 字段,静态规则缺省 scope="always");与 /permissions 共享实例由
			// gate 注入面承载(无头路径无命令面,直接装配)。
			configGate = new PermissionGate({ mode: permissionModeFromConfig(config.permission?.mode) });
			// config 规则的 ask 动作 = 缺省语义,门禁静态层(allow/deny)不表,装配时剔除;
			// 显式构造(不用展开+窄化推断,与仓库 TS 版本的推断行为解耦)。
			const staticRules: PermissionRule[] = [];
			for (const rule of config.permission?.rules ?? []) {
				if (rule.action === "ask") continue;
				staticRules.push({ tool: rule.tool, pattern: rule.pattern, action: rule.action, scope: "always" });
			}
			configGate.addRules(staticRules);
		} catch (cause) {
			if (cause instanceof ConfigError || cause instanceof ModelPortConfigError) {
				err(`bi: ${cause.message}`);
				return 3;
			}
			throw cause;
		}
	}

	try {
		const result = await runHeadless({
			prompt: parsed.prompt,
			cwd: h.cwd ?? process.cwd(),
			model,
			tools: h.tools ?? [],
			...(h.hooks !== undefined ? { hooks: h.hooks } : {}),
			...(h.sessionsRoot !== undefined ? { sessionsRoot: h.sessionsRoot } : {}),
			...(h.permissionMode !== undefined ? { permissionMode: h.permissionMode } : {}),
			...(h.gate !== undefined ? { gate: h.gate } : {}),
			...(configGate !== undefined ? { gate: configGate } : {}),
			...(h.trust !== undefined ? { trust: h.trust } : {}),
			...(h.hookSpawn !== undefined ? { hookSpawn: h.hookSpawn } : {}),
			// CLI --max-rounds 优先于 deps 透传（BI-30 dogfood 发现：真实工单 8 回合不够）。
			...((parsed.maxRounds ?? h.maxRounds) !== undefined
				? { maxRounds: parsed.maxRounds ?? h.maxRounds }
				: {}),
			...(options.out !== undefined ? { out: options.out } : {}),
		});
		return result.exitCode;
	} catch (cause) {
		const message = cause instanceof Error ? cause.message : String(cause);
		err(`bi: 会话失败: ${message}`);
		return 1;
	}
}

/**
 * BI-20.2 · 全局参数矩阵 parseGlobalArgs 测试。
 *
 * 覆盖：四个长参（空格/等号传值）、--add-dir 可重复聚合、-- 终止符、
 * 裸位置参数收集、未知参数/缺值（末尾与后随 flag/单独 -）/非法值/
 * 重复单值 flag 的结构化报错、GLOBAL_ARGS 矩阵定义完整性。
 */
import { describe, expect, test } from "bun:test";
import { ArgParseError, GLOBAL_ARGS, parseGlobalArgs } from "./args";

function catchCode(run: () => unknown): { code: ArgParseError["code"]; flag?: string } {
  try {
    run();
  } catch (error) {
    if (error instanceof ArgParseError) return { code: error.code, flag: error.flag };
    throw error;
  }
  throw new Error("预期解析失败，但成功了");
}

describe("BI-20.2 parseGlobalArgs：正常解析", () => {
  test("四个长参空格传值全解析", () => {
    const parsed = parseGlobalArgs([
      "--agent-file",
      "agents/bi.md",
      "--add-dir",
      "/tmp/x",
      "--prompt",
      "帮我看看",
      "--output-format",
      "stream-json",
    ]);
    expect(parsed.agentFile).toBe("agents/bi.md");
    expect(parsed.addDirs).toEqual(["/tmp/x"]);
    expect(parsed.prompt).toBe("帮我看看");
    expect(parsed.outputFormat).toBe("stream-json");
    expect(parsed.positionals).toEqual([]);
  });

  test("等号形式传值", () => {
    const parsed = parseGlobalArgs(["--agent-file=a.md", "--prompt=你好"]);
    expect(parsed.agentFile).toBe("a.md");
    expect(parsed.prompt).toBe("你好");
  });

  test("--add-dir 可重复出现并按顺序聚合", () => {
    const parsed = parseGlobalArgs(["--add-dir", "/a", "--add-dir=/b", "--add-dir", "/c"]);
    expect(parsed.addDirs).toEqual(["/a", "/b", "/c"]);
  });

  test("裸位置参数收集进 positionals（子命令派发归属装配方）", () => {
    const parsed = parseGlobalArgs(["init", "--prompt", "p"]);
    expect(parsed.positionals).toEqual(["init"]);
    expect(parsed.prompt).toBe("p");
  });

  test("-- 终止符之后全部视为位置参数", () => {
    const parsed = parseGlobalArgs(["--", "x", "--prompt", "-y"]);
    expect(parsed.positionals).toEqual(["x", "--prompt", "-y"]);
    expect(parsed.prompt).toBeUndefined();
  });

  test("空 argv → 空结果", () => {
    expect(parseGlobalArgs([])).toEqual({ addDirs: [], positionals: [] });
  });

  test("等号形式可传 `-` 开头的字面值", () => {
    const parsed = parseGlobalArgs(["--prompt=--continue"]);
    expect(parsed.prompt).toBe("--continue");
  });
});

describe("BI-20.2 parseGlobalArgs：结构化报错", () => {
  test("未知参数 → unknown-flag（flag 字段回传参名）", () => {
    const { code, flag } = catchCode(() => parseGlobalArgs(["--unknown"]));
    expect(code).toBe("unknown-flag");
    expect(flag).toBe("--unknown");
  });

  test("末尾缺值 → missing-value", () => {
    const { code, flag } = catchCode(() => parseGlobalArgs(["--agent-file"]));
    expect(code).toBe("missing-value");
    expect(flag).toBe("--agent-file");
  });

  test("后随另一 flag 视为缺值 → missing-value", () => {
    const { code, flag } = catchCode(() => parseGlobalArgs(["--prompt", "--add-dir", "/x"]));
    expect(code).toBe("missing-value");
    expect(flag).toBe("--prompt");
  });

  test("后随单独 `-` 视为缺值 → missing-value", () => {
    const { code } = catchCode(() => parseGlobalArgs(["--prompt", "-"]));
    expect(code).toBe("missing-value");
  });

  test("--output-format 非法值 → invalid-value", () => {
    const { code, flag } = catchCode(() => parseGlobalArgs(["--output-format", "text"]));
    expect(code).toBe("invalid-value");
    expect(flag).toBe("--output-format");
  });

  test("--output-format 合法值 stream-json 通过", () => {
    expect(parseGlobalArgs(["--output-format=stream-json"]).outputFormat).toBe("stream-json");
  });

  test("单值 flag 重复出现 → duplicate-flag", () => {
    const { code, flag } = catchCode(() =>
      parseGlobalArgs(["--prompt", "a", "--prompt", "b"]),
    );
    expect(code).toBe("duplicate-flag");
    expect(flag).toBe("--prompt");
  });

  test("可重复 flag（--add-dir）重复不报 duplicate-flag", () => {
    expect(parseGlobalArgs(["--add-dir", "/a", "--add-dir", "/b"]).addDirs).toEqual(["/a", "/b"]);
  });

  test("--max-rounds 正整数通过并转 number", () => {
    expect(parseGlobalArgs(["--max-rounds", "24"]).maxRounds).toBe(24);
    expect(parseGlobalArgs(["--max-rounds=1"]).maxRounds).toBe(1);
  });

  test("--max-rounds 非正整数 → invalid-value", () => {
    // 负数以 "-" 开头,按既有契约走 missing-value（与 --prompt 遇 "-" 同规）。
    const { code } = catchCode(() => parseGlobalArgs(["--max-rounds", "-3"]));
    expect(code).toBe("missing-value");
    for (const bad of ["0", "2.5", "abc"]) {
      const { code, flag } = catchCode(() => parseGlobalArgs(["--max-rounds", bad]));
      expect(code).toBe("invalid-value");
      expect(flag).toBe("--max-rounds");
    }
  });
});

describe("BI-20.2 GLOBAL_ARGS：矩阵定义完整性", () => {
  test("包含五个合约旗标且定义字段齐备", () => {
    expect(GLOBAL_ARGS.map((s) => s.flag)).toEqual([
      "--agent-file",
      "--add-dir",
      "--prompt",
      "--output-format",
      "--max-rounds",
    ]);
    for (const spec of GLOBAL_ARGS) {
      expect(spec.flag.startsWith("--")).toBe(true);
      expect(spec.valueName.length).toBeGreaterThan(0);
      expect(spec.description.length).toBeGreaterThan(0);
      expect(typeof spec.repeatable).toBe("boolean");
    }
  });

  test("可重复性与值域约束按合约定义", () => {
    const byFlag = new Map(GLOBAL_ARGS.map((s) => [s.flag, s]));
    expect(byFlag.get("--add-dir")?.repeatable).toBe(true);
    expect(byFlag.get("--agent-file")?.repeatable).toBe(false);
    expect(byFlag.get("--prompt")?.repeatable).toBe(false);
    expect(byFlag.get("--output-format")?.allowedValues).toEqual(["stream-json"]);
    expect(byFlag.get("--agent-file")?.valueName).toBe("<path.md>");
  });
});

/**
 * BI-23.1 走骨架点火端到端验收（RULE-BI-12 首卡）。
 *
 * 验收硬标准：一条确定性会话贯通全部装配环节——
 * kimi 序 main 分发 → JSONL 会话落盘（BI-03）→ 钩子触发（真实子进程，BI-06.4
 * 经 BI-01.1 装载适配器）→ 权限门（BI-06.5）→ agent 工具流水线（BI-07）→
 * 真实 fs 工具执行 → stream-json 线合约（BI-04.2 StreamEvent 原样透传）。
 * 模型端口为脚本化注入（零网络；真实驱动随 BI-23.3）。
 */
import { describe, expect, test } from "bun:test";
import { mkdtemp, mkdir, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { runBi } from "./main";
import { runHeadless, type ModelPort, type ToolBinding } from "./headless";
import { SessionManager } from "../session/manager";
import type { AgentMessage, StreamEvent } from "../adapters/deepseek-adapter";
import type { HooksSection } from "../config/schema";

/** 脚本化模型端口：按回合回放事件序列，并捕获收到的消息流供接线断言。 */
function scriptedModel(rounds: StreamEvent[][]): {
	port: ModelPort;
	received: Array<{ messages: readonly AgentMessage[]; tools: readonly string[] }>;
} {
	const received: Array<{ messages: readonly AgentMessage[]; tools: readonly string[] }> = [];
	let cursor = 0;
	const port: ModelPort = {
		async *stream(input) {
			const round = rounds[cursor];
			cursor += 1;
			if (round === undefined) throw new Error(`scripted-model: 第 ${cursor} 回合无脚本`);
			received.push({ messages: [...input.messages], tools: input.tools.map((t) => t.name) });
			for (const event of round) yield event;
		},
	};
	return { port, received };
}

function readFileSyncBinding(cwd: string): ToolBinding {
	return {
		definition: {
			name: "read_file",
			description: "读取工作区内文本文件",
			inputSchema: { type: "object", properties: { path: { type: "string" } }, required: ["path"] },
		},
		readOnly: true,
		argSummary: (args) => String((args as { path?: string }).path ?? ""),
		execute: async (args) => {
			const path = (args as { path?: string }).path;
			if (typeof path !== "string" || path === "") throw new Error("path required");
			const abs = resolve(cwd, path);
			if (!abs.startsWith(resolve(cwd))) throw new Error("path-escape");
			return await Bun.file(abs).text();
		},
	};
}

const TOOL_ROUND: StreamEvent[] = [
	{ type: "content_delta", delta: "我来读取文件。" },
	{ type: "tool_call_delta", index: 0, id: "call_1", name: "read_file", argumentsDelta: '{"path":"note.txt"}' },
	{ type: "usage", usage: { inputTokens: 12, outputTokens: 8 } },
	{ type: "done", stopReason: "tool_use" },
];

async function makeWorkspace(): Promise<{ root: string; cleanup: () => Promise<void> }> {
	const root = await mkdtemp(join(tmpdir(), "bi-skel-"));
	await writeFile(join(root, "note.txt"), "勾稽差额为零", "utf8");
	return { root, cleanup: () => rm(root, { recursive: true, force: true }) };
}

const ALLOW_HOOK = 'echo \'{"action":"allow"}\'';

describe("BI-23.1 走骨架点火（端到端）", () => {
	test("全链路点亮：真实工具执行 + 钩子触发 + 权限门 + JSONL 落盘 + stream-json 线", async () => {
		const { root, cleanup } = await makeWorkspace();
		try {
			const { port, received } = scriptedModel([
				TOOL_ROUND,
				[
					{ type: "content_delta", delta: "文件内容是：勾稽差额为零。" },
					{ type: "usage", usage: { inputTokens: 30, outputTokens: 9 } },
					{ type: "done", stopReason: "stop" },
				],
			]);
			const lines: string[] = [];
			const result = await runHeadless({
				prompt: "读取 note.txt 并总结",
				cwd: root,
				model: port,
				tools: [readFileSyncBinding(root)],
				hooks: {
					enabled: true,
					entries: [
						{ event: "session_start", command: ALLOW_HOOK, timeout_ms: 5_000, matcher: "", blocking: true },
						{ event: "pre_tool_use", command: ALLOW_HOOK, timeout_ms: 5_000, matcher: "", blocking: true },
					],
				},
				sessionsRoot: join(root, "sessions"),
				out: (line) => lines.push(line),
			} as Parameters<typeof runHeadless>[0]);

			expect(result.exitCode).toBe(0);
			expect(result.rounds).toBe(2);
			expect(result.finalText).toContain("勾稽差额为零");
			expect(result.toolResults).toHaveLength(1);
			expect(result.toolResults[0]!.ok).toBe(true);
			// 真实 fs 执行：工具读回文件真实内容
			expect(safeValue(result.toolResults[0]!)).toContain("勾稽差额为零");
			// 权限门：auto 模式放行 + 审计轨迹
			expect(result.permissionDecisions).toEqual([{ tool: "read_file", decision: "allow" }]);
			// 钩子：真实子进程执行，SessionStart 与 PreToolUse 均 ran 且决策 allow
			const ranEvents = result.hookRecords.filter((r) => r.status === "ran").map((r) => r.event);
			expect(ranEvents).toContain("SessionStart");
			expect(ranEvents).toContain("PreToolUse");
			expect(result.hookRecords.filter((r) => r.event === "PreToolUse" && r.status === "ran").every((r) => r.decision === "allow")).toBe(true);

			// JSONL 会话：user → assistant(tool_use) → tool_call → tool_result → assistant(最终)
			const manager = new SessionManager({ rootDir: join(root, "sessions") });
			const entries = await manager.entries(result.sessionId);
			expect(entries.map((e) => e.type)).toEqual(["user", "assistant", "tool_call", "tool_result", "assistant"]);
			const toolResultEntry = entries.find((e) => e.type === "tool_result");
			expect(JSON.stringify(toolResultEntry?.payload)).toContain("勾稽差额为零");
			expect(toolResultEntry?.toolName).toBe("read_file");

			// 模型侧接线：第二回合收到 tool_result 回填（含真实工具输出）
			expect(received).toHaveLength(2);
			const secondRoundMessages = received[1]!.messages;
			const lastMessage = secondRoundMessages.at(-1);
			expect(lastMessage?.role).toBe("user");
			expect(JSON.stringify(lastMessage?.content)).toContain("勾稽差额为零");
			// 工具定义面喂给模型
			expect(received[0]!.tools).toEqual(["read_file"]);

			// stream-json 线合约：首行 content_delta，末行 session_done 汇总
			const parsed = lines.map((line) => JSON.parse(line) as { type: string });
			expect(parsed[0]!.type).toBe("content_delta");
			expect(parsed.some((e) => e.type === "tool_call_delta")).toBe(true);
			const done = parsed.at(-1)!;
			expect(done.type).toBe("session_done");
			expect((done as { type: string; exit?: string }).exit).toBe("ok");
		} finally {
			await cleanup();
		}
	});

	test("PreToolUse 钩子阻断：fail-closed 回喂模型，工具不执行", async () => {
		const { root, cleanup } = await makeWorkspace();
		try {
			const { port } = scriptedModel([
				TOOL_ROUND,
				[
					{ type: "content_delta", delta: "钩子拒绝读取，我停止。" },
					{ type: "done", stopReason: "stop" },
				],
			]);
			const result = await runHeadless({
				prompt: "读取 note.txt",
				cwd: root,
				model: port,
				tools: [readFileSyncBinding(root)],
				hooks: {
					enabled: true,
					entries: [{ event: "pre_tool_use", command: 'echo \'{"action":"block","reason":"policy"}\'', timeout_ms: 5_000, matcher: "", blocking: true }],
				},
				sessionsRoot: join(root, "sessions"),
				out: () => {},
			} as Parameters<typeof runHeadless>[0]);

			expect(result.exitCode).toBe(0);
			expect(result.toolResults[0]!.ok).toBe(false);
			expect(result.toolResults[0]!.error).toContain("hook-blocked");
			expect(result.toolResults[0]!.error).toContain("policy");
			const preRecords = result.hookRecords.filter((r) => r.event === "PreToolUse");
			expect(preRecords.some((r) => r.status === "ran" && r.decision === "block")).toBe(true);
		} finally {
			await cleanup();
		}
	});

	test("manual 模式 ask 降级：无头无审批 UI，结构化拒绝回喂（不假冒放行）", async () => {
		const { root, cleanup } = await makeWorkspace();
		try {
			const { port } = scriptedModel([
				TOOL_ROUND,
				[
					{ type: "content_delta", delta: "权限未授，停止。" },
					{ type: "done", stopReason: "stop" },
				],
			]);
			const result = await runHeadless({
				prompt: "读取 note.txt",
				cwd: root,
				model: port,
				tools: [readFileSyncBinding(root)],
				permissionMode: "manual",
				sessionsRoot: join(root, "sessions"),
				out: () => {},
			} as Parameters<typeof runHeadless>[0]);

			expect(result.permissionDecisions).toEqual([{ tool: "read_file", decision: "ask" }]);
			expect(result.toolResults[0]!.ok).toBe(false);
			expect(result.toolResults[0]!.error).toContain("permission-ask-unavailable-in-headless");
		} finally {
			await cleanup();
		}
	});
});

function safeValue(result: { value?: unknown }): string {
	return typeof result.value === "string" ? result.value : JSON.stringify(result.value ?? "");
}

